import { action } from "ts-rails";
import { AuthRoute } from "./auth.route";
import { ProfileRoute } from "./profile.route";
import { UserRoute } from "./user.route";
import { CurrentUserMiddleware } from "@middlewares";

this.path(action(CurrentUserMiddleware));
// @irwin:after-current-user
this.path("/auth", AuthRoute.draw());
this.path("/users", UserRoute.draw());
this.path("/me", ProfileRoute.draw());

export * from "./auth.controller";
export * from "./user.controller";
export * from "./profile.controller";

.auth-footer {
  margin-top: 1.25rem;
  font-size: 0.9rem;
  color: #64748b;
  text-align: center;
}

.auth-footer a {
  color: #2563eb;
  font-weight: 600;
}

.site-locale-menu {
  position: relative;
}

.site-locale-menu__trigger {
  list-style: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  border: 1px solid var(--site-border);
  background: var(--site-surface);
  color: var(--site-text);
  font-size: 0.85rem;
  font-weight: 600;
}

.site-locale-menu__trigger::-webkit-details-marker {
  display: none;
}

.site-locale-menu__trigger:hover {
  border-color: #cbd5e1;
  background: var(--site-bg);
}

.site-locale-menu__icon {
  width: 1rem;
  height: 1rem;
  color: var(--site-muted);
}

.site-locale-menu__code {
  line-height: 1;
}

.site-locale-menu__panel {
  position: absolute;
  right: 0;
  top: calc(100% + 0.35rem);
  min-width: 10.5rem;
  background: var(--site-surface);
  border: 1px solid var(--site-border);
  border-radius: 10px;
  box-shadow: 0 8px 24px rgb(15 23 42 / 12%);
  padding: 0.35rem 0;
  z-index: 200;
}

.site-locale-menu__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.5rem 0.85rem;
  color: var(--site-text);
  text-decoration: none;
  font-size: 0.9rem;
}

.site-locale-menu__item:hover {
  background: var(--site-bg);
}

.site-locale-menu__item.is-active {
  background: #eff6ff;
  color: var(--site-accent);
  font-weight: 600;
}

.site-locale-menu__name {
  flex: 1;
}

.site-locale-menu__badge {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--site-muted);
  letter-spacing: 0.02em;
}

.site-locale-menu__item.is-active .site-locale-menu__badge {
  color: var(--site-accent);
}

.profile-card {
  background: var(--site-surface);
  border: 1px solid var(--site-border);
  border-radius: 12px;
  padding: 1.5rem;
}

.profile-form__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

@media (max-width: 640px) {
  .profile-form__grid {
    grid-template-columns: 1fr;
  }
}

.profile-form__full {
  grid-column: 1 / -1;
}

.profile-form label {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-size: 0.9rem;
  color: var(--site-muted);
}

.profile-form input {
  padding: 0.5rem 0.65rem;
  border: 1px solid var(--site-border);
  border-radius: 6px;
  font: inherit;
  color: var(--site-text);
}

.profile-form__actions {
  display: flex;
  gap: 0.75rem;
  margin-top: 1.25rem;
  flex-wrap: wrap;
}

.profile-form__actions button {
  border: none;
  cursor: pointer;
}
